eventScripts.script:
if currentValue.value and not previousValue.value:

    logger = system.util.getLogger("PLC_ACK")

    try:

        # Convert Acknowledged_x -> Active_x
        activeTag = str(tagPath).replace(
            "Acknowledged_",
            "Active_"
        )

        # Build Ignition alarm source
        provider, tag = activeTag.split("]", 1)
        provider = provider.replace("[", "")

        alarmSource = "prov:%s:/tag:%s:/alm:Alarm" % (
            provider,
            tag.lstrip("/")
        )

        logger.info(
            "Looking for: {}".format(alarmSource)
        )

        # Get all alarm events
        alarms = system.alarm.queryStatus()

        for alarm in alarms:

            source = str(alarm.getSource())

            if source == alarmSource:

                logger.info(
                    "Found: ID={} | State={} | Acked={} | Cleared={}".format(
                        alarm.getId(),
                        alarm.getState(),
                        alarm.isAcked(),
                        alarm.isCleared()
                    )
                )

                # Only acknowledge ACTIVE + UNACKNOWLEDGED
                if not alarm.isAcked() and not alarm.isCleared():

                    eventId = str(alarm.getId())

                    logger.info(
                        "Acknowledging Event ID: {}".format(eventId)
                    )

                    system.alarm.acknowledge(
                        [eventId],
                        "Acknowledged from PLC",
                        "PLC"
                    )

                    logger.info(
                        "Acknowledgement command sent."
                    )

                    break

        else:

            logger.warn(
                "Matching Active Unacknowledged alarm not found."
            )

    except Exception as e:

        logger.error(
            "PLC ACK ERROR: {}".format(e)
        )

